create or replace function public.business_location_scoped_analytics(p_business_id uuid,p_location_id uuid,p_dataset text,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language plpgsql security definer set search_path to 'public','pg_temp' as $$ declare r jsonb; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if not exists(select 1 from public.business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and bm.role in ('owner','admin','manager','analyst')) and not exists(select 1 from public.profiles pr where pr.id=auth.uid() and coalesce(pr.is_admin,false)) then raise exception 'Not authorized for this business'; end if; if not exists(select 1 from public.locations l where l.id=p_location_id and l.business_id=p_business_id) then raise exception 'Location does not belong to business'; end if; if p_dataset='overview' then select jsonb_build_object('locations',1,'active_locations',case when is_active then 1 else 0 end,'visits',(select count(*) from location_visits where location_id=p_location_id and occurred_at between p_start and p_end),'unique_users',(select count(distinct user_id) from location_visits where location_id=p_location_id and occurred_at between p_start and p_end),'check_ins',(select count(*) from check_ins where location_id=p_location_id and checked_in_at between p_start and p_end),'reviews',(select count(*) from reviews where location_id=p_location_id and created_at between p_start and p_end and status<>'hidden'),'average_rating',coalesce((select avg(stars) from reviews where location_id=p_location_id and created_at between p_start and p_end and status<>'hidden'),0)) into r from locations where id=p_location_id; elsif p_dataset='engagement' then select jsonb_build_object('visitors',(select count(*) from location_visits where location_id=p_location_id and occurred_at between p_start and p_end),'unique_users',(select count(distinct user_id) from location_visits where location_id=p_location_id and occurred_at between p_start and p_end),'check_ins',(select count(*) from check_ins where location_id=p_location_id and checked_in_at between p_start and p_end),'reviews',(select count(*) from reviews where location_id=p_location_id and created_at between p_start and p_end and status<>'hidden')) into r; elsif p_dataset='reviews' then select jsonb_build_object('reviews',count(*),'average_rating',coalesce(avg(stars),0),'published_reviews',count(*) filter(where status='published'),'business_replies',count(*) filter(where business_reply is not null)) into r from reviews where location_id=p_location_id and created_at between p_start and p_end and status<>'hidden'; elsif p_dataset='photos' then select jsonb_build_object('photos',count(*),'vr_photos',count(*) filter(where lower(coalesce(media_type,'')) in('vr','360','360_vr')),'storage_bytes',coalesce(sum(size_bytes),0)) into r from location_photos where location_id=p_location_id and created_at between p_start and p_end; elsif p_dataset='promotions' then select jsonb_build_object('promotions',count(*),'active_promotions',count(*) filter(where active)) into r from promotions where business_id=p_business_id and location_id=p_location_id; elsif p_dataset='events' then select jsonb_build_object('events',count(*)) into r from business_events where business_id=p_business_id and location_id=p_location_id; elsif p_dataset='contests' then select jsonb_build_object('contests',count(*),'active_contests',count(*) filter(where status='active')) into r from contests where business_id=p_business_id; elsif p_dataset='growth' then select jsonb_build_object('check_ins',count(*),'unique_users',count(distinct user_id)) into r from check_ins where location_id=p_location_id and checked_in_at between p_start and p_end; else r:=jsonb_build_object('message','Unsupported dataset'); end if; return coalesce(r,'{}'::jsonb); end $$;
